	this.particle = new Particle(this.sceneWrapper)




		 // --- 오로라 쉐이더용 풀스크린 플레인 ---
  const auroraVertex = `
    varying vec2 vUv;
    void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }
  `;

  // Simplex noise function (classic implementation) and aurora color bands
  const auroraFragment = `
    precision highp float;
    varying vec2 vUv;
    uniform float time;
    uniform vec2 resolution;

    // 2D Random/Noise - IQ's classic
    vec3 mod289(vec3 x){return x - floor(x * (1.0/289.0)) * 289.0;}
    vec2 mod289(vec2 x){return x - floor(x * (1.0/289.0)) * 289.0;}
    vec3 permute(vec3 x){return mod289(((x*34.0)+1.0)*x);}    
    float snoise(vec2 v){
      const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
      vec2 i = floor(v + dot(v, C.yy));
      vec2 x0 = v - i + dot(i, C.xx);
      vec2 i1 = (x0.x > x0.y) ? vec2(1.0,0.0) : vec2(0.0,1.0);
      vec4 x12 = x0.xyxy + C.xxzz;
      x12.xy -= i1;
      i = mod289(i);
      vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));
      vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
      m = m*m ; m = m*m ;
      vec3 x = 2.0 * fract(p * C.www) - 1.0;
      vec3 h = abs(x) - 0.5;
      vec3 ox = floor(x + 0.5);
      vec3 a0 = x - ox;
      m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
      vec3 g;
      g.x = a0.x * x0.x + h.x * x0.y;
      g.y = a0.y * x12.x + h.y * x12.y;
      g.z = a0.z * x12.z + h.z * x12.w;
      return 130.0 * dot(m, g);
    }

    // palette for aurora
    vec3 auroraPalette(float t){
      vec3 a = vec3(0.02,0.0,0.08);
      vec3 b = vec3(0.0,0.4,0.5);
      vec3 c = vec3(0.2,1.0,0.6);
      vec3 d = vec3(1.0,1.0,0.6);
      if(t<0.25) return mix(a,b, smoothstep(0.0,0.25, t));
      if(t<0.6) return mix(b,c, smoothstep(0.25,0.6,t));
      return mix(c,d, smoothstep(0.6,1.0,t));
    }

    void main(){
      vec2 uv = vUv;
      vec2 p = uv * vec2(resolution.x/resolution.y, 1.0);
      float t = time * 0.05;

      float n = 0.0;
      float freq = 1.0;
      float amp = 1.0;
      for(int i=0;i<5;i++){
        n += snoise(vec2(p.x*freq*2.0, p.y*freq*0.6 - t*float(i)*0.3)) * amp;
        freq *= 2.0; amp *= 0.5;
      }

      // vertical bands with smooth falloff
      float bands = smoothstep(0.1, 0.0, abs(sin((p.x*2.0 + n*0.6 + t*0.2)))) ;
      float shimmer = pow(smoothstep(-0.2,0.6, n), 2.0);
      float intensity = clamp(bands*shimmer, 0.0, 1.0);

      // create multiple layered strips
      float strip = smoothstep(0.0, 0.9, fract((p.y*4.0 + n*1.2 - t*0.6)));
      float combined = intensity * strip;

      vec3 col = auroraPalette(combined);
      // add soft glow and subtle blue background
      vec3 back = vec3(0.01,0.02,0.04) + 0.12*vec3(snoise(p*0.5 + t*0.2));
      vec3 final = mix(back, col, combined);

      // vignette
      float d = distance(uv, vec2(0.5));
      final *= smoothstep(0.9, 0.3, d);

      gl_FragColor = vec4(final, combined*0.9);
    }
  `;

	const auroraMat = new THREE.ShaderMaterial({
		vertexShader: auroraVertex,
		fragmentShader: auroraFragment,
		transparent:true,
		uniforms: {
		time:{value:0},
		resolution:{value:new THREE.Vector2(500, 500)}
		},
		depthWrite:false
	});
	const auroraGeo = new THREE.PlaneGeometry(16,9,1,1);
	const auroraMesh = new THREE.Mesh(auroraGeo, auroraMat);
	auroraMesh.position.set(0,3,-2);
	auroraMesh.rotation.x = -0.25;
	this.sceneWrapper.scene.add(auroraMesh);


