import * as THREE from 'three';

import { RendererCore } from '..';

import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { BokehPass } from 'three/examples/jsm/postprocessing/BokehPass.js';

export class PostProcessingWrapper {
	public threeCore: RendererCore;
	public composer: EffectComposer;
	public blurComposer: EffectComposer;
	blurredReflectionRT: THREE.WebGLRenderTarget;
	reflectorRT;

	private bloomPass: UnrealBloomPass;
	private bokehPass: BokehPass;

	private frame = 0;

	constructor(threeCore: RendererCore) {
		this.threeCore = threeCore;
	}
	public async init() {
		if (this.threeCore.useWebGPU) return;

		const renderTarget = new THREE.WebGLRenderTarget(this.threeCore.host.clientWidth, this.threeCore.host.clientHeight, {
			samples: 4, // optional (for antialiasing)
		});
		renderTarget.depthTexture = new THREE.DepthTexture(this.threeCore.host.clientWidth, this.threeCore.host.clientHeight);
		renderTarget.depthTexture.type = THREE.UnsignedShortType;

		this.composer = new EffectComposer(this.threeCore.renderer as THREE.WebGLRenderer, renderTarget);

		this.initPostProcessing();
	}
	public initPostProcessing() {
		if (this.threeCore.useWebGPU) return;

		this.composer.addPass(new RenderPass(this.threeCore.scene, this.threeCore.cameraWrapper.camera));

		this.bokehPass = new BokehPass(this.threeCore.scene, this.threeCore.cameraWrapper.camera, {
			focus: 100,
			aperture: 0.00008,
			maxblur: 2.0,
		});
		this.composer.addPass(this.bokehPass);
		this.bokehPass.enabled = false;

		this.bloomPass = new UnrealBloomPass(new THREE.Vector2(this.threeCore.host.clientWidth, this.threeCore.host.clientHeight), 0.2, 0.3, 0.6);
		this.composer.addPass(this.bloomPass);
		this.bloomPass.enabled = false;
	}
	public toggleEffect(value: boolean | undefined = undefined) {
		if (value !== undefined) {
			this.bokehPass.enabled = value;
			this.bloomPass.enabled = value;
		} else {
			this.bokehPass.enabled = !this.bokehPass.enabled;
			this.bloomPass.enabled = !this.bloomPass.enabled;
		}
	}
	public render() {
		this.composer.render();

		if ((this.frame++ & 5) === 0) {
			this.bokehPass.materialBokeh.uniforms['focus'].value = this.threeCore.cameraWrapper.getCameraDistance();
		}
	}
}
