import * as THREE from 'three';
import { HypercubeParametric } from '../';
import { Parameters } from '../Parameters/Parameters';

interface WallConfig {
	name: string;
	position: THREE.Vector3;
	rotation: THREE.Euler;
	isOpen: boolean;
}

interface WallState {
	y: number;
	currentY: number;
	angle: number;
}

export class RollingDoor {
	public hypercubeParametric: HypercubeParametric;

	public wallPlain: THREE.InstancedMesh[] = [];

	public mesh: THREE.Mesh[] = [];

	private wallConfigs: WallConfig[] = [];
	private states: WallState[][] = [];

	private hasAnimation = false;
	private selectedIndex = 0;
	private count = 0;

	private dimension: Parameters;
	// Animation constants
	private readonly ANIMATION_SPEED = 1.25;
	private readonly ROLLING_SPEED = 0.05;
	private readonly MAX_ANGLE = Math.PI / 2;
	private readonly OFFSET_FROM_SURFACE = 0.75;

	constructor(hypercubeParametric: HypercubeParametric) {
		this.hypercubeParametric = hypercubeParametric;
		this.dimension = this.hypercubeParametric.params;
		this.init();
	}

	public init(): void {
		this.createWallConfigurations();
		this.createWallMeshes();
	}

	private createWallConfigurations(): void {
		const baseY = this.dimension.groundY + this.dimension.thickness;
		const offset = this.OFFSET_FROM_SURFACE;

		this.wallConfigs = [
			this.createWallConfig('wall-rolling-front', 0, baseY, this.dimension.length * 0.5 - offset, 0, 0, 0),
			this.createWallConfig('wall-rolling-left', this.dimension.width * 0.5 - offset, baseY, 0, 0, Math.PI * 0.5, 0),
			this.createWallConfig('wall-rolling-back', 0, baseY, -this.dimension.length * 0.5 + offset, 0, -Math.PI, 0),
			this.createWallConfig('wall-rolling-right', -this.dimension.width * 0.5 + offset, baseY, 0, 0, -Math.PI * 0.5, 0),
		];
	}

	private createWallConfig(name: string, x: number, y: number, z: number, rx: number, ry: number, rz: number): WallConfig {
		return {
			name,
			position: new THREE.Vector3(x, y, z),
			rotation: new THREE.Euler(rx, ry, rz),
			isOpen: false,
		};
	}

	private createWallMeshes(): void {
		this.wallConfigs.forEach((config, index) => {
			const mesh = this.createWallMesh(config, index);
			mesh.castShadow = mesh.receiveShadow = true;
			this.wallPlain.push(mesh);
			this.addMeshToScene(mesh);
		});
	}

	private createWallMesh(config: WallConfig, index: number): THREE.InstancedMesh {
		const { geometry } = this.hypercubeParametric.exoSkeletonMeshes;
		const material = this.hypercubeParametric.configurator.materials.skinMaterial;
		this.count = this.calculateWallCount();

		const mesh = new THREE.InstancedMesh(geometry, material, this.count);
		this.setupMeshProperties(mesh, config.name);
		this.populateInstancedMesh(mesh, config, index);
		this.applyMeshTransform(mesh, config);

		return mesh;
	}

	private calculateWallCount(): number {
		const { height, WallUnit, thickness } = this.dimension;
		const totalHeight = height - thickness * 1.5;
		return calculateCount(totalHeight, WallUnit.height, WallUnit.heightGap);
	}

	private setupMeshProperties(mesh: THREE.InstancedMesh, name: string): void {
		mesh.name = name;
		mesh.castShadow = true;
		mesh.receiveShadow = true;
	}

	private populateInstancedMesh(mesh: THREE.InstancedMesh, config: WallConfig, index: number): void {
		const dummy = new THREE.Object3D();
		const { height, heightGap, thickness } = this.dimension.WallUnit;
		const states: WallState[] = [];
		let currentY = 0;

		for (let row = 0; row < this.count; row++) {
			const isEvenRow = row % 2 === 0;
			const z = isEvenRow ? 0 : -thickness * 0.5;
			const scaleY = isEvenRow ? height : heightGap;
			const scaleX = this.getWallWidth(config.name);

			dummy.position.set(0, currentY + scaleY / 2, z);
			dummy.scale.set(scaleX, scaleY, thickness);
			dummy.rotation.set(0, 0, 0);
			dummy.updateMatrix();

			mesh.setMatrixAt(row, dummy.matrix);

			states[row] = {
				y: dummy.position.y,
				currentY: dummy.position.y,
				angle: 0,
			};

			currentY += scaleY;
		}
		this.states.push(states);
	}

	private getWallWidth(wallName: string): number {
		const { width, length, thickness, epsilon } = this.dimension;
		const adjustment = thickness * 2 + epsilon;

		return wallName.includes('front') || wallName.includes('back') ? width - adjustment : length - adjustment;
	}

	private applyMeshTransform(mesh: THREE.InstancedMesh, config: WallConfig): void {
		mesh.position.copy(config.position);
		mesh.rotation.copy(config.rotation);
	}

	private addMeshToScene(mesh: THREE.InstancedMesh): void {
		this.mesh.push(mesh);
		this.hypercubeParametric.configurator.sceneWrapper.scene.add(mesh);
	}

	public getIndex(meshName: string): number {
		return this.wallConfigs.findIndex((config, index) => {
			if (config.name === meshName) {
				return true;
			}
			return false;
		});
	}
	public toggleRollingDoorByID(name: string = ''): void {
		// console.log(name)
		const selIndex = this.getIndex(name);
		if (selIndex === -1) return;

		this.selectedIndex = selIndex;
		const config = this.wallConfigs[selIndex];

		config.isOpen = !config.isOpen;
		this.hasAnimation = true;

		this.hypercubeParametric.wall.openDoorSliding(config.isOpen);
		// console.log(name)
	}
	public toggleDoorAll() { }
	public update(): boolean {
		if (!this.hasAnimation) return false;
		this.animateRollingDoor(this.selectedIndex);

		return this.hasAnimation;
	}

	private animateRollingDoor(index: number): void {
		const limit = this.dimension.height - this.dimension.thickness * 1.5;
		const openY = limit * 0.8;
		const offsetFromSurface = 0.25;
		const mesh = this.wallPlain[index];
		const isOpen = this.wallConfigs[index].isOpen;

		// Check if animation is complete
		if ((isOpen && this.states[index][0].currentY > openY) || (!isOpen && this.states[index][0].currentY <= 0.5)) {
			this.hasAnimation = false;
			// console.log('Animation complete!');
			return;
		}

		const dummy = new THREE.Object3D();

		for (let i = 0; i < this.count; i++) {
			const state = this.states[index][i];
			this.updateWallState(state, limit, isOpen);
			this.updateDummyTransform(dummy, state, i, index, limit, offsetFromSurface);
			mesh.setMatrixAt(i, dummy.matrix);
		}

		mesh.instanceMatrix.needsUpdate = true;
	}

	private updateWallState(state: WallState, limit: number, isOpen: boolean): void {
		if (isOpen) {
			if (state.currentY < limit) {
				state.currentY = Math.min(state.currentY + this.ANIMATION_SPEED, limit);
			}
			if (state.currentY >= limit) {
				state.angle = Math.min(state.angle + this.ROLLING_SPEED, this.MAX_ANGLE);
			}
		} else {
			state.angle = 0;
			state.currentY = Math.max(state.currentY - this.ANIMATION_SPEED, state.y);
		}
	}

	private updateDummyTransform(dummy: THREE.Object3D, state: WallState, i: number, index: number, limit: number, offsetFromSurface: number): void {
		const z = i % 2 === 0 ? this.dimension.WallUnit.thickness * 0.5 : 0;
		const sx = index % 2 === 0 ? this.dimension.width : this.dimension.length;
		const sy = i % 2 === 0 ? this.dimension.WallUnit.height : this.dimension.WallUnit.heightGap;

		dummy.scale.set(sx - this.dimension.thickness * 2, sy, this.dimension.WallUnit.thickness);

		if (state.currentY >= limit) {
			dummy.position.set(0, state.currentY, z - offsetFromSurface * 5);
			dummy.rotation.set(state.angle + i, 0, 0);
		} else {
			dummy.position.set(0, state.currentY, z - offsetFromSurface);
			dummy.rotation.set(state.angle, 0, 0);
		}
		dummy.updateMatrix();
	}
	public syncSizes(): void {
		this.rebuild();
	}
	public rebuild(): void {
		this.cleanup();
		this.init();
	}

	private cleanup(): void {
		this.wallPlain.forEach((obj) => {
			this.hypercubeParametric.configurator.sceneWrapper.scene.remove(obj);
		});
		this.wallPlain = [];
		this.states = [];
		this.mesh = [];
	}
}

const calculateCount = (totalHeight: number, ys: number, ysOffset: number): number => {
	let currentY = 0;
	let count = 0;

	while (currentY < totalHeight) {
		const height = count % 2 === 0 ? ys : ysOffset;
		if (currentY + height > totalHeight) break;
		currentY += height;
		count++;
	}
	return count;
};
